import java.io.*;
import java.util.*;

public class B {
    public static void main(String[] args) throws IOException {
        Reader k = new Reader(System.in);
        PrintWriter z = new PrintWriter(System.out);
        while (k.hasNext()) {
            int n = k.nextInt();
            String s = k.next();
            boolean inside = false;
            boolean wordStart = true;
            int insideWords = 0;
            StringBuilder cur = new StringBuilder();
            StringBuilder best = new StringBuilder();
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (c == '(') {
                    inside = true;
                    wordStart = true;
                    cur.setLength(0);
                } else if (c == ')') {
                    inside = false;
                    cur.setLength(0);
                } else if (!inside) {
                    if (c == '_') {
                        cur.setLength(0);
                    } else {
                        cur.append(c);
                    }
                    if (cur.length() > best.length()) {
                        best.setLength(0);
                        best.append(cur);
                    }
                } else {
                    if (c == '_') {
                        wordStart = true;
                    } else if (wordStart) {
                        insideWords++;
                        wordStart = false;
                    }
                }
            }
            z.println(best.length() + " " + insideWords);
        }
        z.flush();
    }

    static class Reader {
        BufferedReader br;
        StringTokenizer st;
        Reader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }
        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
